class Solution {
public:
    typedef long long ll;
    string nearestPalindromic(string n) {
        if(n.size()==1)
            return to_string(stoll(n)-1);
        ll ans;
        vector<ll> vals;
        ll digits=n.size();
        ll mid=(digits+1)/2;
        ll prefix=stoll(n.substr(0,mid));
        vals.push_back(pow(10,digits-1)-1);
        vals.push_back(pow(10,digits)+1);
        vector<ll> pres={prefix,prefix+1,prefix-1};
        for(auto it:pres)
        {
            string temp=to_string(it);
            if(digits%2!=0)
                temp.pop_back();
            reverse(temp.begin(),temp.end());
            string str=to_string(it)+temp;
            vals.push_back(stoll(str));
        }
        ll diff=INT_MAX;
        ll num=stoll(n);
        for(int i=0;i<5;i++)
        {
            if((num!=vals[i]) and abs(num-vals[i])<diff)
            {
                ans=(vals[i]);
                diff=abs(num-vals[i]);
            }
            else if(abs(num-vals[i])==diff)
                ans=(min(ans,vals[i]));
        }
        for(auto it:vals)
            cout<<it<<" ";
        return to_string(ans);
    }
};

class Solution(object):
    def nearestPalindromic(self, n):
        """
        :type n: str
        :rtype: str
        """
        m = len(n)
        candidates = [10 ** (m - 1) - 1, 10 ** m + 1]
        prefix = int(n[:(m + 1) // 2])
        for x in range(prefix - 1, prefix + 2):
            if m % 2 == 0:
                y = x
            else:
                y = x // 10
            while y:
                x = x * 10 + y % 10
                y = y // 10
            candidates.append(x)

        ans = None
        for candidate in candidates:
            if candidate != int(n):
                if (ans is None or
                    abs(candidate - int(n)) < abs(ans - int(n)) or
                    (abs(candidate - int(n)) == abs(ans - int(n)) and candidate < ans)):
                    ans = candidate
        return str(ans)
